window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e394b6a49758b5d6"]={"versions": [{"id": "FIG-e394b6a49758b5d6", "releases": ["R20-11", "R21-11", "R22-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Zeitablauf- und Datenflussdiagramm (Timing/Execution Schedule Diagram) für Multi-Core-/Inter-Task-Kommunikation.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (ab R20-11, spezifiziert in <code>AUTOSAR_CP_EXP_SwClusterDesignAndIntegrationGuideline</code>). Dargestellt ist der funktionale Determinizismus von Software-Clustern (SWCs) auf Mehrkernsystemen durch das <strong>Logical Execution Time (LET)</strong>-Paradigma im Vergleich zum klassischen, ausführungszeitabhängigen RTE-Kommunikationsmodell.</li>\n<li><strong>Funktionaler Zweck:</strong> Nachweis, wie LET das Problem von Abtast-Jitter und Dateninkonsistenzen (Wechsel zwischen $N$- und $N-1$-Werten) eliminiert, wenn sich durch Software-Updates oder Integration neuer Cluster die Task-Laufzeiten und Ausführungszeitpunkte von Runnables verschieben.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>OS-Tasks / LET-Intervalle:</strong></li>\n<li><code>LET01Core1</code>: Periodischer OS-Task auf Core 1 mit fest definiertem LET-Intervall zwischen den Zeitpunkten <code>release</code> (Task-Aktivierung) und <code>terminate</code> (logisches Periodenende/Deadline).</li>\n<li><code>LET01Core2</code>: Periodischer OS-Task auf Core 2 mit synchronem/korrespondierendem LET-Intervall [<code>release</code>, <code>terminate</code>].</li>\n<li><strong>Runnables & Software-Komponenten (SWC):</strong></li>\n<li><code>Rp</code> (<em>Runnable Provider / Producer</em>): Sende-Runnable innerhalb von <code>LET01Core1</code>, implementiert den Datenausgang (Sender/Provider-Port).</li>\n<li><code>Rr</code> (<em>Runnable Receiver / Consumer</em>): Empfangs-Runnable innerhalb von <code>LET01Core2</code>, verarbeitet die Eingangsdaten (Receiver-Port).</li>\n<li><strong>Ausführungszustände (visuelle Kodierung):</strong></li>\n<li><em>Schraffierter Balken:</em> Vorlaufzeit / Response-Time-Verzögerung (Wartezeit, Scheduling-Jitter, Ausführung anderer Runnables oder Unterbrechung durch höherpriore Tasks).</li>\n<li><em>Blauer Balken:</em> Tatsächliches Ausführungsintervall des jeweiligen Runnables (<code>Rp</code> bzw. <code>Rr</code>).</li>\n<li><strong>Puffer / Schnittstellen-Semantik:</strong></li>\n<li><em>Klassische Kommunikation:</em> Direkter Zugriff auf gemeinsame Speicherbereiche/RTE-Puffer (ohne LET-Buffer-Entkopplung).</li>\n<li><em>LET-Kommunikation:</em> RTE-seitige LET-Input- und LET-Output-Buffer (Shadow-Register/Copy-In/Copy-Out-Mechanismus).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Szenario 1 (Rp terminiert spät, Rr startet früh)</p>\n<ul class=\"fig-list\">\n<li><strong>Klassischer Ablauf (ohne LET):</strong></li>\n<li><code>Rr</code> wird auf Core 2 ausgeführt, bevor <code>Rp</code> auf Core 1 gerechnet hat.</li>\n<li><code>Rr</code> liest den alten Datenstand aus der vorherigen Periode ($N-1$). Es entsteht ein <em>Backward Dataflow</em> (roter Pfeil weist zeitlich zurück).</li>\n<li><strong>LET-basierter Ablauf:</strong></li>\n<li>Daten werden erst am logischen Endpunkt <code>terminate</code> von <code>LET01Core1</code> freigegeben und stehen am logischen Startpunkt <code>release</code> von <code>LET01Core2</code> für die Folgeperiode zur Verfügung (<em>Guaranteed Backward Dataflow</em>, grüner Pfad).</li>\n</ul>\n<p class=\"fig-p\">#### Szenario 2 (Rp terminiert früh, Rr startet spät)</p>\n<ul class=\"fig-list\">\n<li><strong>Ursache:</strong> Geänderte Task-Last, Integration eines neuen SW-Clusters oder variierende Worst-Case Execution Time (WCET).</li>\n<li><strong>Klassischer Ablauf (ohne LET):</strong></li>\n<li><code>Rp</code> schreibt die Daten auf Core 1 bereits fertig, bevor <code>Rr</code> auf Core 2 mit dem Lesen beginnt.</li>\n<li><code>Rr</code> liest den neuen Datenstand der aktuellen Periode ($N$). Es entsteht ein <em>Forward Dataflow</em> (roter Pfeil weist nach rechts/vorwärts).</li>\n<li><strong>Fehlerbild im klassischen Modus:</strong> Nicht-deterministischer Wechsel zwischen Datenalter $N$ und $N-1$ (<em>Random forward / backward Dataflow</em>). Regelschleifen erfahren unvorhersehbare Totzeiten und Phasen-Jitter.</li>\n<li><strong>LET-basierter Ablauf:</strong></li>\n<li>Trotz verfrühter Ausführung von <code>Rp</code> bleibt der Veröffentlichungszeitpunkt strikt an <code>terminate</code> gebunden; das Einlesen von <code>Rr</code> bleibt strikt an <code>release</code> gebunden. Das funktionale Verhalten bleibt 100 % identisch zu Szenario 1.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-Konfiguration & Codegenerierung:</strong></li>\n<li>Bei Aktivierung von LET (<code>RteUseLet = true</code>) instanziiert der RTE-Generator separate Lese- und Schreib-Puffer (Double-/Triple-Buffering) sowie Synchronisationsmechanismen (LET Task Wrappers oder Core-Hooks).</li>\n<li><code>Rte_Write</code> schreibt in den lokalen Task-Output-Puffer; der globale Datenübertrag erfolgt erst beim Task-Terminierungs-Event (<code>terminate</code>).</li>\n<li><code>Rte_Read</code> greift auf einen Puffer zu, der exakt zum Task-Aktivierungszeitpunkt (<code>release</code>) eingefroren wurde.</li>\n<li><strong>Speicher- und Laufzeit-Overhead:</strong></li>\n<li>Erhöhter RAM-Bedarf durch deterministische Kopierpuffer pro Kommunikationsbeziehung über Core- und Taskgrenzen hinweg.</li>\n<li>Kopier-Overhead (<code>memcpy</code>) zu Beginn (<code>release</code>) und am Ende (<code>terminate</code>) der Task-Instanz.</li>\n<li><strong>Einschränkung für Regelungs-Algorithmen:</strong></li>\n<li>Der Entwickler muss eine systembedingte Transportlatenz von mindestens einer LET-Periode ($N-1 \\rightarrow N$) in Kauf nehmen. Direkte Intra-Period-Reaktionen innerhalb desselben Zeitschritts über Core-Grenzen hinweg sind unter reinem LET-Backward-Dataflow per Definition ausgeschlossen.</li>\n<li><strong>Cluster-Unabhängigkeit:</strong></li>\n<li>Entwickler einzelner Software-Cluster können ihre Runnables zeitlich modifizieren oder neu integrieren, ohne Seiteneffekte auf das funktionale Verhalten anderer Cluster zu erzeugen, solange die Tasks innerhalb ihres definierten LET-Budgets ([<code>release</code>, <code>terminate</code>]) fertigstellen.</li>\n</ul>"}, {"id": "FIG-75fa96eba964f125", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Zeitablauf- und Datenflussdiagramm (Timing/Execution Schedule Diagram) für Multi-Core-/Inter-Task-Kommunikation.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (ab R20-11, spezifiziert in <code>AUTOSAR_CP_EXP_SwClusterDesignAndIntegrationGuideline</code>). Dargestellt ist der funktionale Determinizismus von Software-Clustern (SWCs) auf Mehrkernsystemen durch das <strong>Logical Execution Time (LET)</strong>-Paradigma im Vergleich zum klassischen, ausführungszeitabhängigen RTE-Kommunikationsmodell.</li>\n<li><strong>Funktionaler Zweck:</strong> Nachweis, wie LET das Problem von Abtast-Jitter und Dateninkonsistenzen (Wechsel zwischen $N$- und $N-1$-Werten) eliminiert, wenn sich durch Software-Updates oder Integration neuer Cluster die Task-Laufzeiten und Ausführungszeitpunkte von Runnables verschieben.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>OS-Tasks / LET-Intervalle:</strong></li>\n<li><code>LET01Core1</code>: Periodischer OS-Task auf Core 1 mit fest definiertem LET-Intervall zwischen den Zeitpunkten <code>release</code> (Task-Aktivierung) und <code>terminate</code> (logisches Periodenende/Deadline).</li>\n<li><code>LET01Core2</code>: Periodischer OS-Task auf Core 2 mit synchronem/korrespondierendem LET-Intervall [<code>release</code>, <code>terminate</code>].</li>\n<li><strong>Runnables & Software-Komponenten (SWC):</strong></li>\n<li><code>Rp</code> (<em>Runnable Provider / Producer</em>): Sende-Runnable innerhalb von <code>LET01Core1</code>, implementiert den Datenausgang (Sender/Provider-Port).</li>\n<li><code>Rr</code> (<em>Runnable Receiver / Consumer</em>): Empfangs-Runnable innerhalb von <code>LET01Core2</code>, verarbeitet die Eingangsdaten (Receiver-Port).</li>\n<li><strong>Ausführungszustände (visuelle Kodierung):</strong></li>\n<li><em>Schraffierter Balken:</em> Vorlaufzeit / Response-Time-Verzögerung (Wartezeit, Scheduling-Jitter, Ausführung anderer Runnables oder Unterbrechung durch höherpriore Tasks).</li>\n<li><em>Blauer Balken:</em> Tatsächliches Ausführungsintervall des jeweiligen Runnables (<code>Rp</code> bzw. <code>Rr</code>).</li>\n<li><strong>Puffer / Schnittstellen-Semantik:</strong></li>\n<li><em>Klassische Kommunikation:</em> Direkter Zugriff auf gemeinsame Speicherbereiche/RTE-Puffer (ohne LET-Buffer-Entkopplung).</li>\n<li><em>LET-Kommunikation:</em> RTE-seitige LET-Input- und LET-Output-Buffer (Shadow-Register/Copy-In/Copy-Out-Mechanismus).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Szenario 1 (Rp terminiert spät, Rr startet früh)</p>\n<ul class=\"fig-list\">\n<li><strong>Klassischer Ablauf (ohne LET):</strong></li>\n<li><code>Rr</code> wird auf Core 2 ausgeführt, bevor <code>Rp</code> auf Core 1 gerechnet hat.</li>\n<li><code>Rr</code> liest den alten Datenstand aus der vorherigen Periode ($N-1$). Es entsteht ein <em>Backward Dataflow</em> (roter Pfeil weist zeitlich zurück).</li>\n<li><strong>LET-basierter Ablauf:</strong></li>\n<li>Daten werden erst am logischen Endpunkt <code>terminate</code> von <code>LET01Core1</code> freigegeben und stehen am logischen Startpunkt <code>release</code> von <code>LET01Core2</code> für die Folgeperiode zur Verfügung (<em>Guaranteed Backward Dataflow</em>, grüner Pfad).</li>\n</ul>\n<p class=\"fig-p\">#### Szenario 2 (Rp terminiert früh, Rr startet spät)</p>\n<ul class=\"fig-list\">\n<li><strong>Ursache:</strong> Geänderte Task-Last, Integration eines neuen SW-Clusters oder variierende Worst-Case Execution Time (WCET).</li>\n<li><strong>Klassischer Ablauf (ohne LET):</strong></li>\n<li><code>Rp</code> schreibt die Daten auf Core 1 bereits fertig, bevor <code>Rr</code> auf Core 2 mit dem Lesen beginnt.</li>\n<li><code>Rr</code> liest den neuen Datenstand der aktuellen Periode ($N$). Es entsteht ein <em>Forward Dataflow</em> (roter Pfeil weist nach rechts/vorwärts).</li>\n<li><strong>Fehlerbild im klassischen Modus:</strong> Nicht-deterministischer Wechsel zwischen Datenalter $N$ und $N-1$ (<em>Random forward / backward Dataflow</em>). Regelschleifen erfahren unvorhersehbare Totzeiten und Phasen-Jitter.</li>\n<li><strong>LET-basierter Ablauf:</strong></li>\n<li>Trotz verfrühter Ausführung von <code>Rp</code> bleibt der Veröffentlichungszeitpunkt strikt an <code>terminate</code> gebunden; das Einlesen von <code>Rr</code> bleibt strikt an <code>release</code> gebunden. Das funktionale Verhalten bleibt 100 % identisch zu Szenario 1.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-Konfiguration & Codegenerierung:</strong></li>\n<li>Bei Aktivierung von LET (<code>RteUseLet = true</code>) instanziiert der RTE-Generator separate Lese- und Schreib-Puffer (Double-/Triple-Buffering) sowie Synchronisationsmechanismen (LET Task Wrappers oder Core-Hooks).</li>\n<li><code>Rte_Write</code> schreibt in den lokalen Task-Output-Puffer; der globale Datenübertrag erfolgt erst beim Task-Terminierungs-Event (<code>terminate</code>).</li>\n<li><code>Rte_Read</code> greift auf einen Puffer zu, der exakt zum Task-Aktivierungszeitpunkt (<code>release</code>) eingefroren wurde.</li>\n<li><strong>Speicher- und Laufzeit-Overhead:</strong></li>\n<li>Erhöhter RAM-Bedarf durch deterministische Kopierpuffer pro Kommunikationsbeziehung über Core- und Taskgrenzen hinweg.</li>\n<li>Kopier-Overhead (<code>memcpy</code>) zu Beginn (<code>release</code>) und am Ende (<code>terminate</code>) der Task-Instanz.</li>\n<li><strong>Einschränkung für Regelungs-Algorithmen:</strong></li>\n<li>Der Entwickler muss eine systembedingte Transportlatenz von mindestens einer LET-Periode ($N-1 \\rightarrow N$) in Kauf nehmen. Direkte Intra-Period-Reaktionen innerhalb desselben Zeitschritts über Core-Grenzen hinweg sind unter reinem LET-Backward-Dataflow per Definition ausgeschlossen.</li>\n<li><strong>Cluster-Unabhängigkeit:</strong></li>\n<li>Entwickler einzelner Software-Cluster können ihre Runnables zeitlich modifizieren oder neu integrieren, ohne Seiteneffekte auf das funktionale Verhalten anderer Cluster zu erzeugen, solange die Tasks innerhalb ihres definierten LET-Budgets ([<code>release</code>, <code>terminate</code>]) fertigstellen.</li>\n</ul>"}], "trans": [{"from": "FIG-e394b6a49758b5d6", "to": "FIG-75fa96eba964f125", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
